    # Check if the graph is connected
    visited = set()
    def dfs(node):
        stack = [node]
        while stack:
            current = stack.pop()
            if current not in visited:
                visited.add(current)
                for neighbor, _ in adj_list[current]:
                    if neighbor not in visited:
                        stack.append(neighbor)

