    def assign_incomes(node, parent, income):
        incomes[node] = income
        for neighbor, b in adj_list[node]:
            if neighbor == parent:
                continue
            if b == 1:
                if incomes[neighbor] != -1 and incomes[neighbor] != income + 1:
